public static int countChar(String str, char ch) {
    int count = 0;
    for (int i = 0; i < str.length(); i++) {
        if (str.charAt(i) == ch) {
            count++;
        }
    }
    return count;
}

public static String reverse(String str) {
    String result = "";
    for (int i = str.length() - 1; i >= 0; i--) {
        result = result + str.charAt(i);
    }
    return result;
}

public static int CountChar(string str, char ch)
{
    int count = 0;
    for (int i = 0; i < str.Length; i++)
    {
        if (str[i] == ch)
        {
            count++;
        }
    }
    return count;
}

public static string Reverse(string str)
{
    string result = "";
    for (int i = str.Length - 1; i >= 0; i--)
    {
        result = result + str[i];
    }
    return result;
}
